window.GESPEICHERTE_DATEN = {"https://valorant-api.com/v1/agents?isPlayableCharacter=true&language=de-DE":{"status":200,"data":[{"uuid":"e370fa57-4757-3604-3648-499e1f642d3f","displayName":"Gekko","description":"Gekko der Angeleno führt eine eingeschworene Truppe verrückter Kreaturen. Seine Freunde springen voran und vertreiben Gegner, während Gekko ihnen folgt, um sie einzusammeln und von vorne anzufangen.","displayIcon":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/fullportrait.png","background":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/background.png","backgroundGradientColors":["371c5cff","0f1923ff","3a2656ff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Wingman","description":"RÜSTE einen zerstörbaren <whitebold>Wingman</> AUS. FEUERE, um ihn auszusenden. <debuffred>Verfolgt</> den ersten Gegner, den er sieht, und <debuffred>betäubt</> ihn beim Aufprall. ALT. FEUERMODUS, damit <whitebold>Wingman</> an einem anvisierten Areal platziert oder entschärft.\r\n\r\nVerwandelt sich in eine <whitebold>Kugel</> zurück.","displayIcon":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Dizzy","description":"RÜSTE einen zerstörbaren <whitebold>Dizzy</> AUS. FEUERE, um ihn zu werfen. Feuert Plasma auf Gegner in Sichtweite und <debuffred>blendet</> sie.\r\n\r\nVerwandelt sich in eine <whitebold>Kugel</> zurück.","displayIcon":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Mosh-Pit","description":"RÜSTE <whitebold>Mosh</> AUS. FEUERE, um ihn zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. Bei der Landung wird eine Zone erschaffen, die geringen <debuffred>Schaden</> über Zeit verursacht, bevor sie explodiert und allen Spielern hohen <debuffred>Schaden</> zufügt.\r\n\r\nVerwandelt sich in eine <whitebold>Kugel</> zurück.","displayIcon":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Thrash","description":"RÜSTE einen zerstörbaren <whitebold>Thrash</> AUS. FEUERE, um die Kontrolle zu übernehmen. FEUERE erneut, um nach vorne zu springen, zu explodieren und alle Spieler zu <debuffred>hindern</>. FEUERE beim Springen, um die Explosion vorzeitig auszulösen.\r\n\r\nVerwandelt sich nur einmal in eine <whitebold>Kugel</> zurück.","displayIcon":"https://media.valorant-api.com/agents/e370fa57-4757-3604-3648-499e1f642d3f/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Kugel","description":"Gekkos Fähigkeiten verwandeln sich nach ihrem Einsatz in eine <whitebold>Kugel</>.\r\n\r\nINTERAGIERE, um <whitebold>Kugeln</> in der Nähe aufzuheben und nach einer kurzen Abklingzeit eine weitere Ladung zu erhalten.","displayIcon":null}]},{"uuid":"dade69b4-4f5a-8528-247b-219e5a1facd6","displayName":"Fade","description":"Die türkische Kopfgeldjägerin Fade entlockt Gegnern mit der Macht der Albträume ihre Geheimnisse. Sie arbeitet mit dem Schrecken selbst zusammen, jagt ihre Ziele und enthüllt deren Ängste – bevor sie sie in der Dunkelheit zermalmt.","displayIcon":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/fullportrait.png","background":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/background.png","backgroundGradientColors":["1d2846ff","0f1923ff","18344cff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Ergreifen","description":"RÜSTE <whitebold>Ergreifen</> AUS. FEUERE, um zu werfen. REAKTIVIERE zur vorzeitiger Landung. Bei der Landung werden Gegner <debuffred>taub</> gemacht, mit <debuffred>Verfall</> belegt und <debuffred>verankert</>.","displayIcon":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Nachtalb","description":"RÜSTE einen zerstörbaren <whitebold>Nachtalb</> AUS. FEUERE, um ihn zu werfen. REAKTIVIERE zur vorzeitiger Landung. <debuffred>Markiert</> und <debuffred>enthüllt</> bei der Landung Gegner in Reichweite und Sichtlinie.","displayIcon":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Nachtschatten","description":"RÜSTE einen zerstörbaren <whitebold>Nachtschatten</> AUS. FEUERE, um ihn auszusenden. HALTE FEUERN, um in Richtung deines Fadenkreuzes zu steuern. <debuffred>Verfolgt</> den ersten erblickten Gegner oder die erste <whitebold>Terrorspur</> und <debuffred>schränkt deren Sicht ein</>, wenn er sie erreicht.","displayIcon":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Einbruch der Nacht","description":"RÜSTE <whitebold>Einbruch der Nacht</> AUS. FEUERE, um eine Welle auszusenden, die Gegner <debuffred>taub</> macht, mit <debuffred>Verfall</> belegt und <debuffred>markiert</>.","displayIcon":"https://media.valorant-api.com/agents/dade69b4-4f5a-8528-247b-219e5a1facd6/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Terrorspuren","description":"<debuffred>Markierte</> Gegner werden durch <whitebold>Terrorspuren</> aufgespürt.","displayIcon":null}]},{"uuid":"5f8d3a7f-467b-97f3-062c-13acf203c006","displayName":"Breach","description":"Der bionisch augmentierte Schwede Breach verursacht gezielt mächtige, kinetische Explosionen, die ohne Rücksicht auf Verluste den Weg frei räumen. Der Schaden und die Massenkontrolle stellen sicher, dass kein Kampf je fair ist.","displayIcon":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/fullportrait.png","background":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/background.png","backgroundGradientColors":["81331aff","0f1923ff","523a23ff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Blitzladung","description":"RÜSTE eine <whitebold>Blitzladung</> AUS. FEUERE, um sie durch eine Wand zu schicken, wo sie explodiert und alle Spieler, die sie ansehen, <debuffred>blendet</>.","displayIcon":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Verwerfungslinie","description":"RÜSTE <whitebold>Verwerfungslinie</> AUS. HALTE FEUERN, um die Distanz zu erhöhen. LASS LOS, um eine Zone zu detonieren, die alle Spieler <debuffred>betäubt</>.","displayIcon":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Nachbeben","description":"RÜSTE <whitebold>Nachbeben</> AUS. FEUERE, um eine Zone durch eine Wand zu schicken, die dann explodiert und allen Spielern mehrfach <debuffred>Schaden</> zufügt.","displayIcon":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Thors Hammer","description":"RÜSTE <whitebold>Thors Hammer</> AUS. FEUERE, um eine Welle auszusenden, die alle Spieler <debuffred>betäubt</> und <debuffred>in die Luft schleudert</>.","displayIcon":"https://media.valorant-api.com/agents/5f8d3a7f-467b-97f3-062c-13acf203c006/abilities/ultimate/displayicon.png"}]},{"uuid":"cc8b64c8-4b25-4ff9-6e7f-37b4da43d235","displayName":"Deadlock","description":"Die norwegische Elitesoldatin Deadlock bedient sich verschiedener High-Tech-Nanodrahtgeräte, um das Schlachtfeld vor den tödlichsten Angriffen zu schützen. Nichts und niemand entgeht ihren Argusaugen und ihre Entschlossenheit hat noch jeden Gegner zur Strecke gebracht.","displayIcon":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/fullportrait.png","background":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/background.png","backgroundGradientColors":["425495ff","0f1923ff","221c3dff","0f192300"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Geräuschsensor","description":"RÜSTE einen zerstörbaren <whitebold>Geräuschsensor</> AUS. FEUERE, um ihn zu platzieren. Wird durch Geräusche von Gegnern in der Nähe ausgelöst und erschafft eine Zone, die alle Spieler <debuffred>betäubt</>. <whitebold>Geräuschsensor</> <teal>tarnt sich</> nach dem Platzieren.\r\n\r\nKann aufgehoben werden.","displayIcon":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/abilities/ability1/displayicon.png"},{"slot":"Grenade","displayName":"Gitterbarriere","description":"RÜSTE <whitebold>Gitterbarriere</> AUS. FEUERE, um sie zu werfen. Erzeuge bei der Landung zerstörbare Markierungen, die sich nach einer Verzögerung verstärken. Die Markierungen bilden Barrieren, die die Bewegung von Spielern blockieren.","displayIcon":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/abilities/grenade/displayicon.png"},{"slot":"Ability2","displayName":"GravNet","description":"RÜSTE <whitebold>GravNet</> AUS. FEUERE, um es zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. Explodiert bei der Landung und zwingt alle Spieler, sich zu <debuffred>ducken</> und sich <debuffred>langsam</> zu bewegen, bis sie das Netz entfernen.","displayIcon":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Annihilation","description":"RÜSTE <whitebold>Annihilation</> AUS. FEUERE, um eine Zone zu starten, die den ersten getroffenen Gegner in einen zerstörbaren Kokon hüllt, der ihn einen Pfad entlangzieht und <debuffred>tödlichen Schaden</> zufügt, außer der Kokon wird zerstört.","displayIcon":"https://media.valorant-api.com/agents/cc8b64c8-4b25-4ff9-6e7f-37b4da43d235/abilities/ultimate/displayicon.png"}]},{"uuid":"b444168c-4e35-8076-db47-ef9bf368f384","displayName":"Tejo","description":"Tejo ist ein kolumbianischer Aufklärungsveteran und besitzt ein ballistisches Leitsystem, mit dem er Gegner dazu zwingt, ihre Stellung aufzugeben … oder sie mit ihrem Leben zu verteidigen. Seine zielgenauen Angriffe bringen Gegner ständig aus dem Konzept und lassen sie nicht zur Ruhe kommen.","displayIcon":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/fullportrait.png","background":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/background.png","backgroundGradientColors":["80451bff","0f1923ff","ffffffff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Ability2","displayName":"Gelenkte Salve","description":"RÜSTE eine taktische Karte AUS. FEUERE, um Zielorte festzulegen. ALT. FEUERMODUS, um Raketen abzufeuern, die dorthin fliegen, wiederholt pulsieren und allen Spielern <debuffred>Schaden</> zufügen.","displayIcon":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/abilities/ability2/displayicon.png"},{"slot":"Ability1","displayName":"Sonderzustellung","description":"RÜSTE <whitebold>Sonderzustellung</> AUS. FEUERE, um zu werfen. ALT. FEUERMODUS, um mit Abpraller zu werfen. Explodiert auf jeder Oberfläche, <debuffred>betäubt</> und <debuffred>verletzt</> alle Spieler.","displayIcon":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/abilities/ability1/displayicon.png"},{"slot":"Ultimate","displayName":"Der Jüngste Tag","description":"RÜSTE eine taktische Karte AUS. FEUERE, um sie zu platzieren, schwenke und FEUERE erneut, um eine Welle zu wirken, die allen Spielern hohen <debuffred>Schaden</> zufügt. ALT. FEUERMODUS, um Zielerfassung abzubrechen.","displayIcon":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/abilities/ultimate/displayicon.png"},{"slot":"Grenade","displayName":"Tarndrohne","description":"RÜSTE eine zerstörbare <whitebold>Tarndrohne</> AUS. FEUERE, um die Kontrolle zu übernehmen. FEUERE erneut, um nahe Gegner in Reichweite und Sichtlinie zu <debuffred>enthüllen</> und zu <debuffred>unterdrücken</>.","displayIcon":"https://media.valorant-api.com/agents/b444168c-4e35-8076-db47-ef9bf368f384/abilities/grenade/displayicon.png"}]},{"uuid":"f94c3b30-42be-e959-889c-5aa313dba261","displayName":"Raze","description":"Die explosive Raze bringt eine laute Persönlichkeit und dicke Knarren aus Brasilien mit. Durch ihre brachiale Spielweise ist sie besonders gut darin, Gegner aufzuscheuchen und beengte Räume mit einer großzügigen Portion „Bumm“ zu säubern.","displayIcon":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/fullportrait.png","background":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/background.png","backgroundGradientColors":["742e1eff","0f1923ff","2c5942ff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Sprengstoffpack","description":"Wirf SOFORT ein zerstörbares <whitebold>Sprengstoffpack</>, das an Oberflächen haftet und nach einer Verzögerung vollständig aufgeladen ist. REAKTIVIERE es, um zu zünden und getroffene Gegner <debuffred>wegzustoßen</>.\r\n\r\nWenn <whitebold>Sprengstoffpacks</> vollständig aufgeladen sind, fügen sie Gegnern auch <debuffred>Schaden</> zu.","displayIcon":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Farbbomben","description":"RÜSTE <whitebold>Farbbomben</> AUS. FEUERE, um sie zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. Explodieren nach Verzögerung, verursachen <debuffred>Schaden</> und erzeugen Streumunition, die ebenfalls allen Spielern <debuffred>Schaden</> zufügt.\r\n\r\nWird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Boom-Bot","description":"RÜSTE einen zerstörbaren <whitebold>Boom-Bot</> AUS. FEUERE, um ihn auszusenden. <debuffred>Verfolgt</> den ersten Gegner, den er sieht, und verursacht beim Aufprall <debuffred>Schaden</> an Gegnern.","displayIcon":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Volles Rohr","description":"Bereite SOFORT <whitebold>Volles Rohr</> vor. FEUERE, um zu werfen. Explodiert auf jeder Oberfläche und fügt allen Spielern hohen <debuffred>Schaden</> zu.","displayIcon":"https://media.valorant-api.com/agents/f94c3b30-42be-e959-889c-5aa313dba261/abilities/ultimate/displayicon.png"}]},{"uuid":"22697a3d-45bf-8dd7-4fec-84a9e28c69d7","displayName":"Chamber","description":"Gut gekleidet und bewaffnet vertreibt der französische Waffendesigner Chamber Angreifer mit tödlicher Präzision. Mit seinem individuellen Arsenal behält er alles im Blick, schaltet Gegner aus der Ferne aus und hat für jeden Plan einen Plan B.","displayIcon":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/fullportrait.png","background":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/background.png","backgroundGradientColors":["20435bff","0f1923ff","372d2bff","0f192300"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Ability2","displayName":"Rendezvous","description":"RÜSTE ein zerstörbares <whitebold>Rendezvous</> AUS. FEUERE, um es zu platzieren. REAKTIVIERE in Reichweite, um dich sofort dorthin zu teleportieren.\r\n\r\nKann zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Markenzeichen","description":"RÜSTE ein zerstörbares <whitebold>Markenzeichen</> AUS. FEUERE, um es zu platzieren. Wird bei sichtbaren Gegnern in der Nähe und in Reichweite ausgelöst und erschafft eine Zone, die alle Spieler <debuffred>verlangsamt</>.\r\n\r\nKann zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"Kopfjäger","description":"RÜSTE <whitebold>Kopfjäger</> AUS. FEUERE, um zu schießen. ALT. FEUERMODUS, um über Visier zu zielen.","displayIcon":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/abilities/ability1/displayicon.png"},{"slot":"Ultimate","displayName":"Glanzleistung","description":"AKTIVIERE, um ein Präzisionsgewehr zu erhalten, das bei direkten Treffern auf den Oberkörper <debuffred>tödlichen Schaden</> verursacht.\r\n\r\nFEUERE, um zu schießen. ALT. FEUERMODUS, um über Visier zu zielen. Bei Kills wird eine Zone erschaffen, die alle Spieler <debuffred>verlangsamt</>.","displayIcon":"https://media.valorant-api.com/agents/22697a3d-45bf-8dd7-4fec-84a9e28c69d7/abilities/ultimate/displayicon.png"}]},{"uuid":"601dbbe7-43ce-be57-2a40-4abd24953621","displayName":"KAY/O","description":"KAY/O ist eine Kriegsmaschine mit nur einem Zweck:  die Neutralisierung von Radiants. Er kann gegnerische Fähigkeiten unterdrücken, womit er Gegenangriffe effektiv verhindert und sich und seinen Verbündeten so den entscheidenden Vorteil verschafft.","displayIcon":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/fullportrait.png","background":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/background.png","backgroundGradientColors":["1c2a69ff","0f1923ff","1a1e4bff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"FRAG/ment","description":"RÜSTE <whitebold>FRAG/ment</> AUS. FEUERE, um es zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. Explodiert bei der Landung und fügt allen Spielern wiederholt <debuffred>Schaden</> zu.","displayIcon":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"BLEND/granate","description":"RÜSTE eine <whitebold>BLEND/granate</> AUS. FEUERE, um sie zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. Explodiert nach Verzögerung und <debuffred>blendet</> alle Spieler, die sie ansehen.","displayIcon":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"NULL/punkt","description":"RÜSTE einen zerstörbaren <whitebold>NULL/punkt</> AUS. FEUERE, um ihn zu werfen. Pulsiert auf jeder Oberfläche und <debuffred>unterdrückt</> Gegner in Reichweite.","displayIcon":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"NULL/cmd","description":"Du erhältst SOFORT <teal>überladen</> und sendest wiederholt einen Impuls aus, der Gegner in Reichweite <debuffred>unterdrückt</>.\r\n\r\n<teal>Überladen</> gewährt <teal>Kampf-Stim</>. Wenn KAY/O <debuffred>tödlichen Schaden</> erleidet, geht er zu Boden und kann restabilisiert werden.","displayIcon":"https://media.valorant-api.com/agents/601dbbe7-43ce-be57-2a40-4abd24953621/abilities/ultimate/displayicon.png"}]},{"uuid":"6f2a04ca-43e0-be17-7f36-b3908627744d","displayName":"Skye","description":"Die Australierin Skye und ihr Rudel bahnen einen Weg durch gegnerisches Gebiet für das Team. Ihre Geschöpfe behindern den Gegner und durch ihre Heilkräfte kann ihrem Team nichts zustoßen, solange es an ihrer Seite ist.","displayIcon":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/fullportrait.png","background":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/background.png","backgroundGradientColors":["436a51ff","0f1923ff","4f1413ff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Bahnbrecher","description":"RÜSTE einen zerstörbaren <whitebold>Bahnbrecher</> AUS. FEUERE, um die Kontrolle zu übernehmen. FEUERE erneut, um nach vorne zu springen, zu explodieren, alle Spieler zu <debuffred>betäuben</> und Gegnern mit direkten Treffern <debuffred>Schaden</> zuzufügen.","displayIcon":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Polarstern","description":"RÜSTE einen <whitebold>Polarstern</> AUS. FEUERE, um ihn auszusenden. HALTE FEUERN, um in Richtung deines Fadenkreuzes zu steuern. REAKTIVIERE, um die Detonation auszulösen und alle Spieler zu <debuffred>blenden</>, die ihn ansehen.","displayIcon":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Gedeihen","description":"RÜSTE <whitebold>Gedeihen</> AUS. HALTE FEUERN, um Verbündete in Reich- und Sichtweite zu <teal>heilen</>. Verwendet eine begrenzte Heilungsleiste.\r\n\r\nKann sich nicht selbst heilen.","displayIcon":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Rudel","description":"RÜSTE ein zerstörbares <whitebold>Rudel</> AUS. FEUERE, um bis zu drei <whitebold>Sucher</> auszusenden. <debuffred>Verfolgt</> die drei nächsten Gegner, <debuffred>schränkt ihre Sicht ein</> und <debuffred>verlangsamt</> sie beim Aufprall.","displayIcon":"https://media.valorant-api.com/agents/6f2a04ca-43e0-be17-7f36-b3908627744d/abilities/ultimate/displayicon.png"}]},{"uuid":"117ed9e3-49f3-6512-3ccf-0cada7e3823b","displayName":"Cypher","description":"Der marokkanische Informationshändler Cypher ist ein Ein-Mann-Überwachungskommando, das die Bewegungen des Gegners genau im Blick behält. Kein Geheimnis ist sicher. Kein Manöver bleibt unbeobachtet. Cypher entgeht nichts.","displayIcon":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/fullportrait.png","background":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/background.png","backgroundGradientColors":["2f5078ff","0f1923ff","3f3f6cff","0f192300"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Cyberkäfig","description":"Wirf SOFORT einen <whitebold>Cyberkäfig</>. INTERAGIERE, um einen Zylinder zu erschaffen, der die Sicht blockiert und ein Audiosignal abspielt, wenn Gegner mit ihm in Kontakt kommen.\r\n\r\nKann während der KAUFPHASE aufgehoben werden.","displayIcon":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Spionagekamera","description":"RÜSTE eine zerstörbare <whitebold>Spionagekamera</> AUS. FEUERE, um sie zu platzieren. <whitebold>Spionagekamera</> <teal>tarnt sich</> nach dem Platzieren. REAKTIVIERE, um sie zu kontrollieren. FEUERE, um einen Pfeil abzuschießen, der getroffene Gegner <debuffred>knipst</>, bis sie ihn entfernen.\r\n\r\nKann aufgehoben werden.","displayIcon":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Fallendraht","description":"RÜSTE einen zerstörbaren <whitebold>Fallendraht</> AUS. FEUERE, um einen Draht zwischen Oberflächen zu platzieren. <whitebold>Fallendraht</> <teal>tarnt sich</> nach dem Platzieren. Wird ausgelöst, wenn Gegner damit in Kontakt kommen. <debuffred>Verankert</> Gegner und <debuffred>enthüllt</> sie nach einer Verzögerung, wenn der <whitebold>Fallendraht</> nicht zerstört wird.\r\n\r\nKann aufgehoben werden.","displayIcon":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Neuronaler Diebstahl","description":"AKTIVIERE bei einem anvisierten toten Gegner. Nach einer Verzögerung werden lebende Gegner zweimal <debuffred>geknipst</>.","displayIcon":"https://media.valorant-api.com/agents/117ed9e3-49f3-6512-3ccf-0cada7e3823b/abilities/ultimate/displayicon.png"}]},{"uuid":"320b2a48-4d9b-a075-30f1-1f93a9b638fa","displayName":"Sova","description":"Sova stammt aus dem ewigen Winter der russischen Tundra und verfolgt, findet und eliminiert Gegner mit gnadenloser Effizienz und Präzision. Sein Spezialbogen und seine unglaublichen Späherfähigkeiten sorgen dafür, dass du zwar fliehen, aber nicht entkommen kannst. ","displayIcon":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/fullportrait.png","background":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/background.png","backgroundGradientColors":["355285ff","0f1923ff","101c47ff","0f192300"],"role":{"displayName":"Initiator","displayIcon":"https://media.valorant-api.com/agents/roles/1b47567f-8f7b-444b-aae3-b0c634622d10/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Schockschuss","description":"RÜSTE einen <whitebold>Schockschuss</> AUS. FEUERE, um einen Bolzen abzuschießen, der auf jeder Oberfläche explodiert und allen Spielern <debuffred>Schaden</> zufügt. HALTE FEUERN, um die Schnelligkeit des Bolzens zu erhöhen. ALT. FEUERMODUS, damit der Schuss bis zu zweimal abprallt.","displayIcon":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Aufklärungsgeschoss","description":"RÜSTE ein zerstörbares <whitebold>Aufklärungsgeschoss</> AUS. FEUERE, um einen Bolzen abzuschießen, der nahe Gegner in Reichweite und Sichtlinie wiederholt <debuffred>enthüllt</>. HALTE FEUERN, um die Schnelligkeit des Bolzens zu erhöhen. ALT. FEUERMODUS, damit der Schuss bis zu zweimal abprallt.","displayIcon":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Eulendrohne","description":"RÜSTE eine zerstörbare <whitebold>Eulendrohne</> AUS. FEUERE, um die Kontrolle zu übernehmen. FEUERE erneut, um einen Pfeil abzuschießen, der Gegner wiederholt <debuffred>enthüllt</>.","displayIcon":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Zorn des Jägers","description":"RÜSTE <whitebold>Zorn des Jägers</> AUS. FEUERE, um einen Bereich zu erzeugen, der <debuffred>Schaden</> verursacht. Kann bis zu zwei weitere Male ausgelöst werden.\r\n\r\nGetroffene Gegner werden für Sova <debuffred>enthüllt</>.","displayIcon":"https://media.valorant-api.com/agents/320b2a48-4d9b-a075-30f1-1f93a9b638fa/abilities/ultimate/displayicon.png"}]},{"uuid":"7c8a4701-4de6-9355-b254-e09bc2a34b72","displayName":"Miks","description":"Miks aus Kroatien betritt die Bühne und kanalisiert pure Soundenergie. Mit seiner ansteckenden Leidenschaft und seinen Schallkräften motiviert er sein Team, als Einheit zu agieren, während sie gemeinsam den Takt auf dem Schlachtfeld angeben.","displayIcon":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/fullportrait.png","background":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/background.png","backgroundGradientColors":["462b75ff","0f1923ff","344673ff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"M-Impuls","description":"RÜSTE einen zerstörbaren <whitebold>M-Impuls</> AUS. ALT. FEUERMODUS, um zwischen <debuffred>Betäubung</> und <teal>Heilung</> umzuschalten. FEUERE, um zu werfen. Pulsiert bei der Landung wiederholt und wendet den ausgewählten Effekt auf alle Spieler in Reichweite an.","displayIcon":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/abilities/grenade/displayicon.png"},{"slot":"Ability2","displayName":"Wellenform","description":"RÜSTE eine taktische Karte AUS. FEUERE, um Rauchpositionen festzulegen. ALT. FEUERMODUS, um Rauch zu aktivieren.","displayIcon":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/abilities/ability2/displayicon.png"},{"slot":"Ability1","displayName":"Harmonisieren","description":"RÜSTE <whitebold>Harmonisieren</> AUS. FEUERE auf einen anvisierten Verbündeten, um ihm und dir <teal>Kampf-Stim</> und <teal>Tempo</> zu gewähren. Solange es aktiv ist, wird der <teal>Buff</> bei Kills erneuert, wenn beide <whitebold>harmonisierten</> Spieler noch am Leben sind. ALT. FEUERMODUS, um ohne Erneuern auf dich selbst zu wirken.","displayIcon":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/abilities/ability1/displayicon.png"},{"slot":"Ultimate","displayName":"Bassbeben","description":"RÜSTE <whitebold>Bassbeben</> AUS. FEUERE, um eine Zone nach vorn zu entsenden, die alle Spieler <debuffred>taub macht</>, <debuffred>zurückstößt</> und <debuffred>verlangsamt</>.","displayIcon":"https://media.valorant-api.com/agents/7c8a4701-4de6-9355-b254-e09bc2a34b72/abilities/ultimate/displayicon.png"}]},{"uuid":"1e58de9c-4950-5125-93e9-a0aee9f98746","displayName":"Killjoy","description":"Das deutsche Genie Killjoy sichert mühelos Schlüsselpositionen auf dem Schlachtfeld mit ihrem Arsenal von Erfindungen. Wenn der Schaden die Gegner nicht ausschaltet, geben ihnen die von den Robotern verteilten Schwächungen den Rest.","displayIcon":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/fullportrait.png","background":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/background.png","backgroundGradientColors":["522162ff","0f1923ff","413950ff","0f192300"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"Nanoschwarm","description":"RÜSTE einen zerstörbaren <whitebold>Nanoschwarm</> AUS. FEUERE, um ihn zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. <whitebold>Nanoschwarm</> <teal>tarnt sich</> nach der Landung. INTERAGIERE, um eine Zone zu erschaffen, die allen Spielern <debuffred>Schaden</> zufügt.\r\n\r\nKann während der KAUFPHASE aufgehoben werden.","displayIcon":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"Alarmbot","description":"RÜSTE einen zerstörbaren <whitebold>Alarmbot</> AUS. FEUERE, um ihn zu platzieren. <whitebold>Alarmbot</> <teal>tarnt sich</> nach dem Platzieren. Wird bei sichtbaren Gegnern in der Nähe und in Reichweite ausgelöst. <debuffred>Verfolgt</> den ersten Gegner, den er sieht, explodiert und verursacht <debuffred>Verwundbar</>.\r\n\r\nKann zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Geschützturm","description":"RÜSTE einen zerstörbaren <whitebold>Geschützturm</> AUS. Wenn ausgerüstet: REAKTIVIERE, um die Richtung zu wechseln, oder halte ALT. FEUERMODUS, um zu drehen. FEUERE, um ihn zu platzieren. Schießt auf Gegner in Sicht.\r\n\r\nKann zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Abriegelung","description":"RÜSTE eine zerstörbare <whitebold>Abriegelung</> AUS. FEUERE, um eine Zone vorzubereiten. <debuffred>Hindert</> Gegner in Reichweite nach einer Verzögerung.","displayIcon":"https://media.valorant-api.com/agents/1e58de9c-4950-5125-93e9-a0aee9f98746/abilities/ultimate/displayicon.png"}]},{"uuid":"95b78ed7-4637-86d9-7e41-71ba8c293152","displayName":"Harbor","description":"Harbor stürmt von Indiens Küsten mit uralter Technologie auf das Feld und beherrscht das Wasser. Er entfesselt Stromschnellen und Sturmfluten, mit denen er seine Verbündeten schützt oder seine Gegner auf Abstand hält.","displayIcon":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/fullportrait.png","background":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/background.png","backgroundGradientColors":["275146ff","0f1923ff","11434eff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Flut","description":"RÜSTE <whitebold>Flut</> AUS. FEUERE, um eine Sicht blockierende Mauer nach vorn zu entsenden, die alle Spieler <debuffred>verlangsamt</>, die mit ihr in Kontakt kommen. HALTE FEUERN, um in Richtung deines Fadenkreuzes zu steuern. ALT. FEUERMODUS, um vorzeitig zu beenden.","displayIcon":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/abilities/ability1/displayicon.png"},{"slot":"Grenade","displayName":"Sturmschwall","description":"RÜSTE <whitebold>Sturmschwall</> AUS. FEUERE, um ihn zu werfen. Explodiert bei der Landung, sorgt bei allen Spielern für <debuffred>eingeschränkte Sicht</> und <debuffred>verlangsamt</> sie.","displayIcon":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/abilities/grenade/displayicon.png"},{"slot":"Ability2","displayName":"Bucht","description":"TRITT in die Tiefe EIN. REAKTIVIERE, um Rauch zu aktivieren. HALTE FEUERN/ALT. FEUERMODUS, um die Distanz anzupassen. LADE NACH, um die Ansicht umzuschalten. REAKTIVIERE nach der Aktivierung, um den Rauch in einen zerstörbaren Panzer zu verwandeln.","displayIcon":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Gissung","description":"RÜSTE <whitebold>Gissung</> AUS. FEUERE, um eine Sicht blockierende Mauer nach vorn zu schieben, die bei allen Spielern, die mit ihr in Kontakt kommen, für <debuffred>eingeschränkte Sicht</> sorgt und sie <debuffred>verlangsamt</>. REAKTIVIERE, um die Mauer vorzeitig aufzuheben.","displayIcon":"https://media.valorant-api.com/agents/95b78ed7-4637-86d9-7e41-71ba8c293152/abilities/ultimate/displayicon.png"}]},{"uuid":"efba5359-4016-a1e5-7626-b1ae76895940","displayName":"Vyse","description":"Das metallmanipulierende Genie Vyse entfesselt flüssiges Metall, um damit ihre Gegner zu isolieren, festzusetzen und zu entwaffnen. Wer sich ihr widersetzt, wird das Schlachtfeld selbst fürchten, wenn sie mit ihren fiesen Tricks und Manipulationen anrückt.","displayIcon":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/fullportrait.png","background":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/background.png","backgroundGradientColors":["492280ff","0f1923ff","ffffffff","0f192300"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Scheren","description":"RÜSTE <whitebold>Scheren</> AUS. FEUERE, um sie zu platzieren. <whitebold>Scheren</> <teal>tarnen sich</> nach dem Platzieren. Wird ausgelöst, wenn Gegner darüberlaufen, und erschafft nach einer Verzögerung kurzzeitig eine unzerstörbare Mauer.\r\n\r\nKann während der KAUFPHASE zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Bogenrose","description":"RÜSTE eine zerstörbare <whitebold>Bogenrose</> AUS. FEUERE, um sie zu platzieren. ALT. FEUERMODUS, um sie durch eine Mauer zu platzieren. REAKTIVIERE, um alle Spieler zu <debuffred>blenden</>, die sie ansehen. \r\n\r\nKann zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Rasiermesserranken","description":"RÜSTE zerstörbare <whitebold>Rasiermesserranken</> AUS. FEUERE, um sie zu werfen. <whitebold>Rasiermesserranken</> <teal>tarnen sich</> nach der Landung. INTERAGIERE, um eine Zone zu erschaffen, die Spieler, die sich hindurchbewegen, <debuffred>verlangsamt</> und ihnen <debuffred>Schaden</> zufügt.\r\n\r\nKann während der KAUFPHASE zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Stahlgarten","description":"RÜSTE <whitebold>Stahlgarten</> AUS. FEUERE, um eine Zone vorzubereiten. Nach einer Verzögerung <debuffred>blockierst</> du gegnerische Primärwaffen in Reichweite.","displayIcon":"https://media.valorant-api.com/agents/efba5359-4016-a1e5-7626-b1ae76895940/abilities/ultimate/displayicon.png"}]},{"uuid":"707eab51-4836-f488-046a-cda6bf494859","displayName":"Viper","description":"Die US-amerikanische Chemikerin Viper setzt eine Reihe von Geräten mit giftigen Chemikalien ein, um die Kontrolle über das Schlachtfeld zu behalten und dem Gegner die Sicht zu nehmen. Falls das Gift ihre Beute nicht zur Strecke bringt, erledigen ihre Psychospielchen das Übrige.","displayIcon":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/fullportrait.png","background":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/background.png","backgroundGradientColors":["1a5f46ff","0f1923ff","2c4f5eff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Giftwolke","description":"RÜSTE <whitebold>Giftwolke</> AUS. FEUERE, um sie zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. REAKTIVIERE, um Treibstoff zu verbrauchen und einen <whitebold>giftigen</> Rauch zu erzeugen, der Gegner <debuffred>verfallen</> lässt.\r\n\r\nKann während der KAUFPHASE aufgehoben werden.","displayIcon":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Toxinschirm","description":"RÜSTE <whitebold>Toxinschirm</> AUS. FEUERE, um eine Linie von Kanistern nach vorne zu entsenden und zu platzieren. REAKTIVIERE, um Treibstoff zu verbrauchen und eine <whitebold>giftige</>, sichtblockierende Mauer zu erzeugen, die Gegner <debuffred>verfallen</> lässt.","displayIcon":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Kontamination","description":"RÜSTE <whitebold>Kontamination</> AUS. FEUERE, um zu werfen. Bei der Landung wird eine Zone erschaffen, die <debuffred>Verwundbar</> auslöst und allen Spielern geringen <debuffred>Schaden</> zufügt.","displayIcon":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Schlangengrube","description":"RÜSTE <whitebold>Schlangengrube</> AUS. FEUERE, um eine große, <whitebold>giftige</>, sichtblockierende Wolke zu erzeugen, die Gegner im Inneren <debuffred>verfallen</> lässt.\r\n\r\nHALTE AKTIVIEREN, um die Wolke aufzulösen.","displayIcon":"https://media.valorant-api.com/agents/707eab51-4836-f488-046a-cda6bf494859/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Toxin","description":"Vipers <whitebold>Toxin</> verursacht kontinuierlich <debuffred>Verfall</>, wenn Gegner damit in Kontakt kommen. Lädt mit der Zeit passiv Treibstoff auf.","displayIcon":null}]},{"uuid":"ddd5a15c-4fbe-42fa-3789-11a55ca5ee04","displayName":"Hush","description":"Die chinesische Agentin Hush nutzt ihre Telekinese, um die geheimsten Fälle abzuschließen. Mit Präzision und Finesse lenkt sie ihre Kampf-Unterstützung mitten in der Luft um, um das gegnerische Team zu stören und zu verschieben, bevor sie es für den Todesstoß hilflos in der Schwebe hält.","displayIcon":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/fullportrait.png","background":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/background.png","backgroundGradientColors":["3d2c44ff","0f1923ff","f47ac7ff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Blitzbirne","description":"RÜSTE <whitebold>Blitzbirne</> AUS. FEUERE, um sie zu werfen. ALT. FEUERMODUS, um sie stattdessen vorzubereiten. REAKTIVIEREN, um sie auf dein Fadenkreuz auszurichten. Explodiert auf jeder Oberfläche oder nach einer Verzögerung und <debuffred>blendet</> alle Spieler, die sie ansehen.","displayIcon":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Verschiebung","description":"RÜSTE <whitebold>Verschiebung</> AUS. FEUERE, um sie zu werfen. ALT. FEUERMODUS, um sie stattdessen vorzubereiten. REAKTIVIEREN, um sie auf dein Fadenkreuz auszurichten. Explodiert auf jeder Oberfläche oder nach einer Verzögerung, <debuffred>zieht</> alle Spieler zur Mitte und <debuffred>betäubt</> sie, wenn sie mit einer Oberfläche oder einem anderen Spieler zusammenstoßen.\r\n\r\nWird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Flow","description":"Erschafft SOFORT einen Anker. Wenn Hush in der Luft ist, schwebt sie kurz an Ort und Stelle. Nach einer Verzögerung fliegt sie zu ihm.","displayIcon":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Sperre","description":"Bereitet SOFORT <whitebold>Sperre</> vor. FEUERE, um sie nach vorne zu schicken und mit dem Fadenkreuz zu steuern. REAKTIVIERE oder FEUERE erneut, um die Detonation auszulösen und alle Spieler <debuffred>in die Luft zu heben</>.","displayIcon":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Telekinese","description":"Hush kann Waffen, den Spike und Schalter aus erhöhter Reichweite aufheben und mit ihnen INTERAGIEREN.","displayIcon":"https://media.valorant-api.com/agents/ddd5a15c-4fbe-42fa-3789-11a55ca5ee04/abilities/passive/displayicon.png"}]},{"uuid":"eb93336a-449b-9c1b-0a54-a891f7921d69","displayName":"Phoenix","description":"Phoenix stammt aus Großbritannien und seine Starqualitäten kommen auch in seinen Kampffähigkeiten zur Geltung. Ob mit oder ohne Verstärkung - der Kampf beginnt, wenn er es sagt.","displayIcon":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/fullportrait.png","background":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/background.png","backgroundGradientColors":["74321cff","0f1923ff","262423ff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"Flammenwand","description":"RÜSTE <whitebold>Flammenwand</> AUS. FEUERE, um eine sichtblockierende <whitebold>Feuerwand</> nach vorn zu entsenden, die allen Spielern <debuffred>Schaden</> zufügt. HALTE FEUERN, um in Richtung deines Fadenkreuzes zu steuern.","displayIcon":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"Heiße Hände","description":"RÜSTE <whitebold>Heiße Hände</> AUS. FEUERE, um zu werfen. ALT. FEUERMODUS für einen Unterhandwurf. Bei der Landung wird eine <whitebold>Feuerzone</> erschaffen, die allen Spielern <debuffred>Schaden</> zufügt.","displayIcon":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Fieser Wurf","description":"RÜSTE <whitebold>Fieser Wurf</> AUS. FEUERE für einen Curvewurf nach links, ALT. FEUERMODUS für einen Curvewurf nach rechts. Explodiert nach Verzögerung und <debuffred>blendet</> alle Spieler, die hinsehen.\r\n\r\nWird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Revanche","description":"Platziere SOFORT eine Markierung an deiner Position. Wenn du <debuffred>tödlichen Schaden</> erleidest oder <whitebold>Revanche</> abläuft, kehrst du mit vollem Leben und dem Rüstungswert bei Aktivierung der Fähigkeit zu der Markierung zurück.","displayIcon":"https://media.valorant-api.com/agents/eb93336a-449b-9c1b-0a54-a891f7921d69/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Inneres Feuer","description":"Phoenix <teal>heilt</> sich, während er in seinem eigenen <whitebold>Feuer</> steht, und erleidet keinen Schaden.","displayIcon":null}]},{"uuid":"92eeef5d-43b5-1d4a-8d03-b3927a09034b","displayName":"Veto","description":"Seine unglaublichen DNA-Mutationen versetzen den senegalesischen Vollstrecker Veto in die Lage, alle Kräfte und Technologien seiner Gegner zu neutralisieren und so die Situation auf dem Schlachtfeld grundlegend umzuwälzen. Auf Vetos Schlachtfeld kannst du dich nur auf deine Waffe verlassen.","displayIcon":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/fullportrait.png","background":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/background.png","backgroundGradientColors":["1a5d65ff","0f1923ff","0f1923ff","1a5d65ff"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Ability2","displayName":"Abfänger","description":"RÜSTE einen zerstörbaren <whitebold>Abfänger</> AUS. FEUERE, um ihn zu platzieren. REAKTIVIERE, um ihn zu aktivieren. Solange aktiv, wird jegliche gegnerische Unterstützung in Reichweite und Sichtlinie zerstört, die beschossen werden kann oder von Spielern abprallen würde.\r\n\r\nKann zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Kreuzhieb","description":"RÜSTE einen zerstörbaren <whitebold>Kreuzhieb</> AUS. FEUERE, um ihn zu platzieren. INTERAGIERE in Reichweite, um dich dorthin zu teleportieren.\r\n\r\nKann während der KAUFPHASE zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Evolution","description":"Erhalte SOFORT <teal>Evolution</>.\r\n\r\n<teal>Evolution</> gewährt <teal>Kampf-Stim</>, kontinuierliche <teal>Heilung</> und <teal>Immunität</> gegen alle Debuffs und jeglichen Schaden, außer durch Waffen.","displayIcon":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/abilities/ultimate/displayicon.png"},{"slot":"Ability1","displayName":"Schwitzkasten","description":"RÜSTE einen zerstörbaren <whitebold>Schwitzkasten</> AUS. FEUERE, um ihn zu werfen. <whitebold>Schwitzkasten</> <teal>tarnt sich</> nach der Landung. Wird bei sichtbaren Gegnern in der Nähe und in Reichweite ausgelöst, <debuffred>macht sie taub</>, lässt sie <debuffred>verfallen</> und <debuffred>verankert</> sie.\r\n\r\nKann während der KAUFPHASE zurückgerufen werden.","displayIcon":"https://media.valorant-api.com/agents/92eeef5d-43b5-1d4a-8d03-b3927a09034b/abilities/ability1/displayicon.png"}]},{"uuid":"41fb69c1-4189-7b37-f117-bcaf1e96f1bf","displayName":"Astra","description":"Die ghanaische Agentin Astra nutzt die Energien des Kosmos, um das Schlachtfeld nach ihren Vorlieben zu verändern. Durch ihre Astralform und ihr Talent für strategische Weitsicht ist sie dem nächsten Zug ihrer Gegner immer Äonen voraus.","displayIcon":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/fullportrait.png","background":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/background.png","backgroundGradientColors":["26146cff","0f1923ff","5210c6ff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Nova-Impuls","description":"AKTIVIERE einen <whitebold>Stern</>, um ihn explodieren zu lassen, was alle getroffenen Spieler <debuffred>betäubt</>.","displayIcon":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Sternnebel","description":"AKTIVIERE einen <whitebold>Stern</>, um ihn in Rauch zu verwandeln.","displayIcon":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Gravitationsbrunnen","description":"AKTIVIERE einen <whitebold>Stern</>, um eine Zone zu erschaffen, die alle Spieler zu ihrer Mitte <debuffred>zieht</>, explodiert und alle Spieler <debuffred>Verwundbar</> macht.","displayIcon":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Astrale Spaltung","description":"TRITT in die <whitebold>Astrale Form</> EIN. ALT. FEUERMODUS, um <whitebold>Astrale Spaltung</> AUSZURÜSTEN. FEUERE, um sie zu platzieren, schwenke und FEUERE erneut, um eine unzerstörbare Mauer zu erzeugen, die Audio blockiert.","displayIcon":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Astralform","description":"AKTIVIERE die ULT, um in deine <whitebold>Astrale Form</> einzutreten. FEUERE, um <whitebold>Sterne</> zu aktivieren. \r\n\r\nINTERAGIERE, um einen <whitebold>Stern</> zurückzurufen. Wenn ein <whitebold>Stern</> zurückgerufen wird, entsteht kurzzeitig Rauch.","displayIcon":"https://media.valorant-api.com/agents/41fb69c1-4189-7b37-f117-bcaf1e96f1bf/abilities/passive/displayicon.png"}]},{"uuid":"9f0d8ba9-4140-b941-57d3-a7ad57c6b417","displayName":"Brimstone","description":"Brimstone kommt aus den USA und sein orbitales Arsenal sorgt dafür, dass sein Team stets einen klaren Vorteil hat. Er sorgt präzise und sicher für Unterstützung, was ihn zu einem perfekten Kommandanten macht.","displayIcon":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/fullportrait.png","background":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/background.png","backgroundGradientColors":["363c4fff","0f1923ff","211d21ff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"Stim-Pack","description":"Wirf SOFORT ein <whitebold>Stim-Pack</>. Bei der Landung wird eine Zone erschaffen, die Verbündeten <teal>Kampf-Stim</> und <teal>Tempo</> gewährt.","displayIcon":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"Brandbeschuss","description":"RÜSTE <whitebold>Brandbeschuss</> AUS. FEUERE, um zu werfen. Bei der Landung wird eine Zone erschaffen, die allen Spielern <debuffred>Schaden</> zufügt.","displayIcon":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Rauch am Himmel","description":"RÜSTE eine taktische Karte AUS. FEUERE, um Rauchpositionen festzulegen. ALT. FEUERMODUS, um Rauch zu aktivieren.","displayIcon":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Luftschlag","description":"RÜSTE eine taktische Karte AUS. FEUERE, um einen <whitebold>Luftschlag</> auf eine Position zu wirken, der allen Spielern hohen <debuffred>Schaden</> über Zeit zufügt.","displayIcon":"https://media.valorant-api.com/agents/9f0d8ba9-4140-b941-57d3-a7ad57c6b417/abilities/ultimate/displayicon.png"}]},{"uuid":"0e38b510-41a8-5780-5e8f-568b2a4f2d6c","displayName":"Iso","description":"Der chinesische Problemlöser Iso kommt in einen Flow und nimmt so seine Gegner auseinander. Er wandelt Umgebungsenergie in kugelsichere Panzerung um und sucht zielstrebig nach seinem nächsten Duell auf Leben und Tod.","displayIcon":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/fullportrait.png","background":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/background.png","backgroundGradientColors":["30336eff","0f1923ff","20155dff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Molekularblitz","description":"RÜSTE einen <whitebold>Molekularblitz</> AUS. FEUERE, um ihn auszusenden. Belegt alle Spieler mit <debuffred>Unterdrückung</> und macht sie <debuffred>verwundbar</>.","displayIcon":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/abilities/ability1/displayicon.png"},{"slot":"Ultimate","displayName":"Auftragsmord","description":"RÜSTE <whitebold>Auftragsmord</> AUS. FEUERE, um eine Zone nach vorne zu entsenden, die dich und den ersten getroffenen Gegner in ein Duell zieht.\r\n\r\nKanalisiere <whitebold>Konzentration</> zu Beginn eines Duells.","displayIcon":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/abilities/ultimate/displayicon.png"},{"slot":"Ability2","displayName":"Dublette","description":"Kanalisiere SOFORT <whitebold>Konzentration</>. Du erhältst einen Panzer, der eine Schadensinstanz blockiert.","displayIcon":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Vorsichtsmaßnahme","description":"RÜSTE <whitebold>Vorsichtsmaßnahme</> AUS. FEUERE, um eine unzerstörbare, sichtblockierende Mauer nach vorne zu schieben. ALT. FEUERMODUS für eine langsamere Mauer.","displayIcon":"https://media.valorant-api.com/agents/0e38b510-41a8-5780-5e8f-568b2a4f2d6c/abilities/grenade/displayicon.png"},{"slot":"Passive","displayName":"Konzentration","description":"Während du <whitebold>konzentriert</> bist, lädst du schneller nach und lässt zerstörbare Energiekugeln aus toten Gegnern entstehen, die durch Iso Schaden erlitten haben oder getötet wurden.\r\n\r\nWird eine Energiekugel abgeschossen, erhältst du einen Panzer, der eine Schadensinstanz abwehrt, und die <whitebold>Konzentration</> wird zurückgesetzt.","displayIcon":null}]},{"uuid":"1dbf2edd-4729-0984-3115-daa5eed44993","displayName":"Clove","description":"Clove aus Schottland ist gut darin, Gegner sowohl in der Hitze des Gefechts als auch angesichts der Kälte des Todes auf Trab zu halten. Clove ist unsterblich und kann selbst aus dem Grab heraus viel Unheil stiften und Gegner im Unklaren über die nächsten Schritte lassen.","displayIcon":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/fullportrait.png","background":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/background.png","backgroundGradientColors":["4b1d80ff","0f1923ff","c347c7ff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"Stärkungsmittel","description":"AKTIVIERE bei einem anvisierten toten Gegner, dem du Schaden zugefügt oder den du getötet hast, um <teal>Tempo</> und <teal>Überheilung</> zu erhalten.","displayIcon":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/abilities/grenade/displayicon.png"},{"slot":"Ability2","displayName":"Täuschung","description":"RÜSTE eine taktische Karte AUS. FEUERE, um Rauchpositionen festzulegen. ALT. FEUERMODUS, um Rauch zu aktivieren.\r\n\r\nWenn Clove tot ist, kannst du auf <whitebold>Täuschung</> zugreifen, um kurzzeitig Rauch zu aktivieren.","displayIcon":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Noch nicht tot","description":"AKTIVIERE bei Tod, um eine <teal>Selbst-Wiederbelebung</> zu kanalisieren. Während der Kanalisierung ist Clove <teal>unberührbar</>. REAKTIVIERE, um das Kanalisieren vorzeitig zu beenden. Sichere dir nach der Wiederbelebung eine Tötung oder eine Schadensunterstützung, um am Leben zu bleiben.","displayIcon":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/abilities/ultimate/displayicon.png"},{"slot":"Ability1","displayName":"Rumpfuschen","description":"RÜSTE <whitebold>Rumpfuschen</> AUS. FEUERE, um zu werfen. Explodiert bei der Landung und lässt alle Spieler <debuffred>verfallen</>.","displayIcon":"https://media.valorant-api.com/agents/1dbf2edd-4729-0984-3115-daa5eed44993/abilities/ability1/displayicon.png"}]},{"uuid":"bb2a4828-46eb-8cd1-e765-15848195d751","displayName":"Neon","description":"Die philippinische Agentin Neon prescht blitzschnell nach vorn und entlädt Blitze aus bioelektrischer Strahlung, die ihr Körper mit einer ebensolchen Geschwindigkeit erzeugt. Sie stürmt vorwärts, um unvorbereitete Gegner zu überraschen und erledigt sie dann mit Lichtgeschwindigkeit.","displayIcon":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/fullportrait.png","background":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/background.png","backgroundGradientColors":["413476ff","0f1923ff","38328eff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability2","displayName":"Hochtourig","description":"Verbrauche SOFORT Treibstoff, um <teal>Tempo</> zu erhalten. REAKTIVIERE, um abzubrechen. ALT. FEUERMODUS, um nach vorne oder in deine Bewegungsrichtung zu rutschen.\r\n\r\nRutschen wird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/abilities/ability2/displayicon.png"},{"slot":"Ability1","displayName":"Relaisblitz","description":"Schleudere SOFORT einen Blitz, der einmal abprallt. Explodiert auf jeder Oberfläche und <debuffred>betäubt</> alle Spieler.","displayIcon":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/abilities/ability1/displayicon.png"},{"slot":"Grenade","displayName":"Überholspur","description":"Schieße SOFORT zwei sichtblockierende Mauern ab, die sich ausbreiten, bis sie auf eine Oberfläche treffen.","displayIcon":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Spannungsspitze","description":"Setzt <whitebold>Hochtourig</> SOFORT zurück. Du erhältst Zugriff auf einen präzisen Blitzstrahl, der während der Aktivierung von <whitebold>Hochtourig</> eingesetzt werden kann.\r\n\r\nFEUERE, um zu schießen. Bei Kills wird der Treibstoff vollständig aufgeladen.","displayIcon":"https://media.valorant-api.com/agents/bb2a4828-46eb-8cd1-e765-15848195d751/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Akku","description":"Lädt mit der Zeit passiv Treibstoff auf.","displayIcon":null}]},{"uuid":"7f94d92c-4234-0a36-9646-3a87eb8b5c89","displayName":"Yoru","description":"Der Japaner Yoru reißt Löcher in die Realität, um unbeobachtet hinter die feindlichen Linien zu gelangen. Er setzt gleichermaßen auf Irreführung und Aggression und ist seinen Gegnern bereits einen Schritt voraus, bevor sie wissen, wie ihnen geschieht.","displayIcon":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/fullportrait.png","background":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/background.png","backgroundGradientColors":["222b67ff","0f1923ff","261e4fff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Grenade","displayName":"IMITATION","description":"RÜSTE <whitebold>Imitation</> AUS. FEUERE, um einen zerstörbaren Klon auszusenden. ALT. FEUERMODUS, um an deiner Position eine Markierung zu platzieren. INTERAGIERE, um die Markierung in einen Klon zu verwandeln.\r\n\r\nKlone bewegen sich kontinuierlich vorwärts und drehen sich zum ersten Gegner, der auf sie schießt, wodurch alle Spieler, die sie ansehen, <debuffred>geblendet</> werden.","displayIcon":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"Überrumpeln","description":"RÜSTE <whitebold>Überrumpeln</> AUS. FEUERE, um zu werfen. Explodiert nach dem Abprallen von einer Oberfläche und <debuffred>blendet</> alle Spieler, die es sehen.","displayIcon":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Überraschungsbesuch","description":"RÜSTE <whitebold>Überraschungsbesuch</> AUS. FEUERE, um ihn auszusenden. ALT. FEUERMODUS, um ihn zu platzieren. REAKTIVIERE, um dich dorthin zu teleportieren. INTERAGIERE, um einen Teleport vorzutäuschen.\r\n\r\nWird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/abilities/ability2/displayicon.png"},{"slot":"Ultimate","displayName":"Dimensionsdrift","description":"RÜSTE <whitebold>Dimensionsdrift</> AUS. FEUERE, um <teal>unberührbar</> und <teal>unsichtbar</> zu werden. <whitebold>Überraschungsbesuch</> ist in diesem Zustand zugänglich. REAKTIVIERE, um vorzeitig zu beenden.","displayIcon":"https://media.valorant-api.com/agents/7f94d92c-4234-0a36-9646-3a87eb8b5c89/abilities/ultimate/displayicon.png"}]},{"uuid":"df1cb487-4902-002e-5c17-d28e83e78588","displayName":"Waylay","description":"Die prismatisch strahlende Waylay aus Thailand verwandelt sich in Licht, wenn sie über das Schlachtfeld flitzt und ihre Ziele mit Lichtsplittern niederschlägt, bevor sie sich blitzschnell in Sicherheit bringt.","displayIcon":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/fullportrait.png","background":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/background.png","backgroundGradientColors":["482e61ff","0f1923ff","0f1923ff","482e61ff"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability2","displayName":"Refraktion","description":"Platziere SOFORT eine Markierung an deiner Position. REAKTIVIERE, um dorthin zu reisen. Während der Reise ist Waylay <teal>immun</>, kann aber keine Gegner sehen.\r\n\r\nWird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Sättigung","description":"RÜSTE <whitebold>Sättigung</> AUS. FEUERE, um sie zu werfen. Explodiert bei der Landung und <debuffred>hindert</> alle Spieler.","displayIcon":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/abilities/grenade/displayicon.png"},{"slot":"Ability1","displayName":"Licht-\r\ngeschwindigkeit","description":"RÜSTE <whitebold>Lichtgeschwindigkeit</> AUS. FEUERE, um zweimal vorwärts zu sprinten. Mit ALT. FEUERMODUS sprintest du nur einmal vorwärts.\r\n\r\nNur der erste Sprint kann dich nach oben befördern.","displayIcon":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/abilities/ability1/displayicon.png"},{"slot":"Ultimate","displayName":"Konvergierende Pfade","description":"RÜSTE <whitebold>Konvergierende Pfade</> AUS. FEUERE, um <teal>Tempo</> zu erhalten und eine Zone nach vorn zu entsenden, die alle Spieler <debuffred>hindert</>.","displayIcon":"https://media.valorant-api.com/agents/df1cb487-4902-002e-5c17-d28e83e78588/abilities/ultimate/displayicon.png"}]},{"uuid":"569fdd95-4d10-43ab-ca70-79becc718b46","displayName":"Sage","description":"Die chinesische Wächterin Sage garantiert Sicherheit für sich und ihr Team, wohin auch immer sie geht. Dank ihrer einzigartigen Fähigkeit, gefallene Verbündete wiederzuerwecken und Angriffe abzuwehren, ist sie auf dem Schlachtfeld das Auge des Sturms.","displayIcon":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/fullportrait.png","background":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/background.png","backgroundGradientColors":["1f5148ff","0f1923ff","102d23ff","0f192300"],"role":{"displayName":"Wächter","displayIcon":"https://media.valorant-api.com/agents/roles/5fc02f99-4091-4486-a531-98459a3e95e9/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Verlangsamungs-\r\nsphäre","description":"RÜSTE eine <whitebold>Verlangsamungssphäre</> AUS. FEUERE, um sie zu werfen. Bei der Landung wird eine Zone erschaffen, die alle Spieler <debuffred>verlangsamt</> und ein Audiosignal abspielt, wenn Gegner hindurchlaufen.","displayIcon":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Heilsphäre","description":"RÜSTE eine <whitebold>Heilsphäre</> AUS. FEUERE auf einen verletzten Verbündeten, um <teal>Heilung</> zu gewähren. ALT. FEUERMODUS, um auf dich selbst zu wirken.","displayIcon":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Barrierensphäre","description":"RÜSTE eine zerstörbare <whitebold>Barrierensphäre</> AUS. Wenn ausgerüstet: REAKTIVIERE, um die Mauer zu schwenken, oder HALTE ALT. FEUERMODUS, um zu drehen. FEUERE, um eine zerstörbare Mauer zu platzieren, die sich nach einer Verzögerung verstärkt.","displayIcon":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Wiederbelebung","description":"RÜSTE <whitebold>Wiederbelebung</> AUS. FEUERE auf einen anvisierten toten Verbündeten, um ihn <teal>wiederzubeleben</>.","displayIcon":"https://media.valorant-api.com/agents/569fdd95-4d10-43ab-ca70-79becc718b46/abilities/ultimate/displayicon.png"}]},{"uuid":"a3bfb853-43b2-7238-a4f1-ad90e9e46bcc","displayName":"Reyna","description":"Reyna wurde im Herzen Mexikos geschmiedet und dominiert den Einzelkampf, indem sie mit jedem Kill, den sie erzielt, auftrumpft. Allein ihr eigenes Können setzt ihren Fähigkeiten Grenzen, weshalb sie extrem abhängig von ihrer Leistung ist. ","displayIcon":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/fullportrait.png","background":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/background.png","backgroundGradientColors":["662d62ff","0f1923ff","2f2664ff","0f192300"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Verzehren","description":"Verbrauche SOFORT eine <whitebold>Seelenkugel</>, um zu <teal>heilen</>. Überschüssige Heilung wird in <teal>Überheilung</> umgewandelt.\r\n\r\nWährend ULT aktiv ist, wird <whitebold>Verzehren</> automatisch gewirkt.","displayIcon":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Eliminieren","description":"Verbrauche SOFORT eine <whitebold>Seelenkugel</>, um kurzzeitig <teal>unberührbar</> zu werden. REAKTIVIERE zum vorzeitigen Abbrechen.\r\n\r\nWährend ULT aktiv ist, erhältst du außerdem <teal>Unsichtbarkeit</>.","displayIcon":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Starren","description":"RÜSTE ein zerstörbares <whitebold>Starren</> AUS. FEUERE, um es auszusenden. Nach einer Verzögerung bildet sich eine Form, die Gegner, die sie ansehen, mit <debuffred>eingeschränkter Sicht</> belegt.","displayIcon":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Kaiserin","description":"Du erhältst SOFORT <teal>Kaiserin</>.\r\n\r\n<teal>Kaiserin</> gewährt <teal>Kampf-Stim</>, endlosen Verbrauch von <whitebold>Seelenkugeln</> und permanente <teal>Überheilung</>.","displayIcon":"https://media.valorant-api.com/agents/a3bfb853-43b2-7238-a4f1-ad90e9e46bcc/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Vitalität","description":"Aus Gegnern, die durch Reyna Schaden erlitten haben oder getötet wurden, lässt du eine <whitebold>Seelenkugel</> entstehen.","displayIcon":null}]},{"uuid":"8e253930-4c05-31dd-1b6c-968525494517","displayName":"Omen","description":"Omen ist das Phantom einer Erinnerung und jagt in den Schatten. Er kann Gegnern die Sicht nehmen und sich über die Karte teleportieren. Wenn die Gegner dann in Panik geraten und sein nächstes Ziel herausfinden wollen, schlägt er zu.","displayIcon":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/fullportrait.png","background":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/background.png","backgroundGradientColors":["433178ff","0f1923ff","344673ff","0f192300"],"role":{"displayName":"Taktiker","displayIcon":"https://media.valorant-api.com/agents/roles/4ee40330-ecdd-4f2f-98a8-eb1243428373/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Paranoia","description":"RÜSTE <whitebold>Paranoia</> AUS. FEUERE, um sie auszusenden. Verursacht bei allen Spielern <debuffred>eingeschränkte Sicht</> und <debuffred>Taubheit</>.","displayIcon":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Finsterer Schleier","description":"TRITT in die Schattensicht ein. REAKTIVIERE, um Rauch zu aktivieren. HALTE FEUERN/ALT. FEUERMODUS, um die Distanz anzupassen. LADE NACH, um die Ansicht umzuschalten.","displayIcon":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Vernebelte Schritte","description":"RÜSTE <whitebold>Vernebelte Schritte</> AUS. FEUERE, um kurz zu kanalisieren und dich dann zur anvisierten Position zu teleportieren.","displayIcon":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Aus den Schatten","description":"RÜSTE eine taktische Karte AUS. FEUERE, um eine Teleportation an einen Zielort zu beginnen. Während des Teleportierens erscheint Omen als zerstörbarer Schatten am Zielort. REAKTIVIERE, um abzubrechen.","displayIcon":"https://media.valorant-api.com/agents/8e253930-4c05-31dd-1b6c-968525494517/abilities/ultimate/displayicon.png"}]},{"uuid":"add6443a-41bd-e414-f6ad-e58d267f4e95","displayName":"Jett","description":"Jett repräsentiert ihre Heimat Südkorea. Sie kämpft agil und weicht geschickt aus, weshalb sie Risiken eingehen kann wie niemand sonst. Sie umrundet Gefechte mit Leichtigkeit und schlitzt Gegner auf, bevor diese wissen, wie ihnen geschieht.","displayIcon":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/displayicon.png","fullPortrait":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/fullportrait.png","background":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/background.png","backgroundGradientColors":["25607aff","0f1923ff","0f1923ff","25607aff"],"role":{"displayName":"Duellant","displayIcon":"https://media.valorant-api.com/agents/roles/dbe8757e-9e92-4ed4-b39f-9dfc589691d4/displayicon.png"},"abilities":[{"slot":"Ability1","displayName":"Aufwind","description":"Katapultiere dich SOFORT hoch in die Luft.","displayIcon":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/abilities/ability1/displayicon.png"},{"slot":"Ability2","displayName":"Rückenwind","description":"Bereite SOFORT einen Sprint vor. REAKTIVIERE, um nach vorne oder in deine Bewegungsrichtung zu sprinten.\r\n\r\nWird nach jedem zweiten Kill zurückgesetzt.","displayIcon":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/abilities/ability2/displayicon.png"},{"slot":"Grenade","displayName":"Wolkenbruch","description":"Wirf SOFORT eine Wolke. Bildet auf jeder Oberfläche oder nach einer Verzögerung kurzzeitig Rauch. HALTE AKTIVIEREN GEDRÜCKT, um in Richtung deines Fadenkreuzes zu steuern.","displayIcon":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/abilities/grenade/displayicon.png"},{"slot":"Ultimate","displayName":"Klingensturm","description":"Du erhältst SOFORT Zugriff auf fünf präzise Wurfmesser, die bei direkten Kopftreffern <debuffred>tödlichen Schaden</> verursachen.\r\n\r\nFEUERE, um zu werfen. Bei Kills werden deine Messer aktualisiert. ALT. FEUERMODUS, um alle verbliebenden Messer ohne Aktualisierung zu werfen.","displayIcon":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/abilities/ultimate/displayicon.png"},{"slot":"Passive","displayName":"Gleiten","description":"HALTE SPRINGEN im Fallen gedrückt, um zu <teal>gleiten</>.","displayIcon":"https://media.valorant-api.com/agents/add6443a-41bd-e414-f6ad-e58d267f4e95/abilities/passive/displayicon.png"}]}]},"https://valorant-api.com/v1/maps?language=de-DE":{"status":200,"data":[{"uuid":"7eaecc1b-4337-bbf6-6ab9-04b8f06b3319","displayName":"Ascent","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/7eaecc1b-4337-bbf6-6ab9-04b8f06b3319/splash.png"},{"uuid":"d960549e-485c-e861-8d71-aa9d1aed12a2","displayName":"Split","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/d960549e-485c-e861-8d71-aa9d1aed12a2/splash.png"},{"uuid":"b529448b-4d60-346e-e89e-00a4c527a405","displayName":"Fracture","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/b529448b-4d60-346e-e89e-00a4c527a405/splash.png"},{"uuid":"2c9d57ec-4431-9c5e-2939-8f9ef6dd5cba","displayName":"Bind","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/2c9d57ec-4431-9c5e-2939-8f9ef6dd5cba/splash.png"},{"uuid":"2fb9a4fd-47b8-4e7d-a969-74b4046ebd53","displayName":"Breeze","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/2fb9a4fd-47b8-4e7d-a969-74b4046ebd53/splash.png"},{"uuid":"224b0a95-48b9-f703-1bd8-67aca101a61f","displayName":"Abyss","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/224b0a95-48b9-f703-1bd8-67aca101a61f/splash.png"},{"uuid":"2fe4ed3a-450a-948b-6d6b-e89a78e680a9","displayName":"Lotus","tacticalDescription":"Areale A/B/C","splash":"https://media.valorant-api.com/maps/2fe4ed3a-450a-948b-6d6b-e89a78e680a9/splash.png"},{"uuid":"92584fbe-486a-b1b2-9faa-39b0f486b498","displayName":"Sunset","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/92584fbe-486a-b1b2-9faa-39b0f486b498/splash.png"},{"uuid":"fd267378-4d1d-484f-ff52-77821ed10dc2","displayName":"Pearl","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/fd267378-4d1d-484f-ff52-77821ed10dc2/splash.png"},{"uuid":"756da597-416b-c0f2-f47b-afbdf28670bc","displayName":"Summit","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/756da597-416b-c0f2-f47b-afbdf28670bc/splash.png"},{"uuid":"e2ad5c54-4114-a870-9641-8ea21279579a","displayName":"Icebox","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/e2ad5c54-4114-a870-9641-8ea21279579a/splash.png"},{"uuid":"1c18ab1f-420d-0d8b-71d0-77ad3c439115","displayName":"Corrode","tacticalDescription":"Areale A/B","splash":"https://media.valorant-api.com/maps/1c18ab1f-420d-0d8b-71d0-77ad3c439115/splash.png"},{"uuid":"2bee0dc9-4ffe-519b-1cbd-7fbe763a6047","displayName":"Haven","tacticalDescription":"Areale A/B/C","splash":"https://media.valorant-api.com/maps/2bee0dc9-4ffe-519b-1cbd-7fbe763a6047/splash.png"}]}};
